1	#!/usr/bin/env node
2	/**
3	 * SessionStart Hook — Stage0 Learned Rules Injector
4	 *
5	 * Parses .claude/rules/learned-rules.md, extracts P0 (blocking) and P1 (advisory) rules,
6	 * writes structured assertions to /tmp/stage0-runtime-assertions-<session>.json, and
7	 * emits a RUNTIME_ASSERTIONS context block consumed by /stage0 Step 0.5.
8	 *
9	 * Root cause fixed: learned-rules.md was decorative (never parsed at runtime). /stage0
10	 * violated own rules [POWER-LAW-MEDIAN-WARNING] + [FORUM-LAYER-PRIORITY] on 2026-04-13
11	 * platform-rev-share-leakage case because rules were never wired.
12	 *
13	 * Fires: SessionStart (startup, resume, clear, compact)
14	 * Exit: 0 (non-blocking, fail-open)
15	 * Plan ref: plans/260413-1002-stage0-bias-fix/phase-01-foundation-learned-rules-and-classifier.md
16	 */
17	
18	try {
19	  const fs = require('fs');
20	  const path = require('path');
21	  const os = require('os');
22	
23	  // P0 rule tags — BLOCKING at /stage0 decision points. Must fire on every session.
24	  // Missing tags are tolerated (e.g. FORUM-LAYER-PRIORITY not yet in master_investments
25	  // learned-rules.md; will be synced in Phase 2).
26	  const P0_TAGS = new Set([
27	    'CONFABULATION-BAN',
28	    'POWER-LAW-MEDIAN-WARNING',
29	    'FORUM-LAYER-PRIORITY',
30	    'TOOL-EXHAUSTION',
31	    'FAILURE-ARCHAEOLOGY-MANDATORY',
32	    'GMV-INCOME-DIVISION',
33	    'FOUNDER-REALITY-GATE',
34	    'BASE-RATE',
35	    'EVIDENCE-RISK',
36	    'BIG-TECH-CHECK',
37	    'EXECUTION-MINDSET-ENFORCEMENT',
38	    'CONTENT-LAYER-MANDATORY',
39	    'STAGE0-PROFILE-BLOCKING',
40	  ]);
41	
42	  // Check ck.json for hook enable flag (defaults to enabled if flag absent)
43	  function isEnabled() {
44	    try {
45	      const ckJsonPath = path.join(process.cwd(), '.claude', '.ck.json');
46	      if (!fs.existsSync(ckJsonPath)) return true;
47	      const cfg = JSON.parse(fs.readFileSync(ckJsonPath, 'utf8'));
48	      const flag = cfg.hooks && cfg.hooks['stage0-learned-rules-injector'];
49	      return flag !== false; // undefined/true = enabled, false = disabled
50	    } catch {
51	      return true;
52	    }
53	  }
54	
55	  // Parse learned-rules.md lines matching: - [TAG] [DOMAIN] body (source: X, date: Y)
56	  function parseRules(rulesPath) {
57	    if (!fs.existsSync(rulesPath)) {
58	      return { p0: [], p1: [], error: 'file_not_found' };
59	    }
60	    const content = fs.readFileSync(rulesPath, 'utf8');
61	    const lines = content.split('\n');
62	    const p0 = [];
63	    const p1 = [];
64	
65	    // Pattern: bullet + [TAG] + optional [DOMAIN] + body + optional (source: ...)
66	    const re = /^-\s*\[([A-Z][A-Z0-9_-]+)\]\s*(?:\[([A-Z]+)\]\s*)?(.+?)(?:\s*\(source:.*?\))?\s*$/;
67	
68	    for (const raw of lines) {
69	      const line = raw.trim();
70	      const m = line.match(re);
71	      if (!m) continue;
72	      const tag = m[1];
73	      const domain = m[2] || 'ALL';
74	      const body = m[3].trim();
75	      const entry = { tag, domain, body: truncate(body, 300) };
76	      if (P0_TAGS.has(tag)) {
77	        p0.push(entry);
78	      } else {
79	        p1.push(entry);
80	      }
81	    }
82	    return { p0, p1, error: null };
83	  }
84	
85	  function truncate(s, max) {
86	    if (!s || s.length <= max) return s;
87	    return s.slice(0, max - 3) + '...';
88	  }
89	
90	  // Write structured assertions to /tmp for /stage0 Step 0.5 consumption
91	  function writeAssertionsFile(sessionId, p0, p1, rulesPath) {
92	    const tmpDir = os.tmpdir();
93	    const filePath = path.join(tmpDir, `stage0-runtime-assertions-${sessionId}.json`);
94	    const payload = {
95	      session_id: sessionId,
96	      written_at: new Date().toISOString(),
97	      rules_source: rulesPath,
98	      p0_count: p0.length,
99	      p1_count: p1.length,
100	      p0_rules: p0,
101	      p1_rules: p1,
102	    };
103	    try {
104	      fs.writeFileSync(filePath, JSON.stringify(payload, null, 2), 'utf8');
105	      return filePath;
106	    } catch {
107	      return null;
108	    }
109	  }
110	
111	  // Emit plain-text context block consumed by Claude Code SessionStart
112	  function emitContextBlock(p0, filePath) {
113	    if (p0.length === 0) {
114	      console.log('\n[stage0-learned-rules-injector] No P0 rules parsed from learned-rules.md');
115	      console.log('  Check file exists + tag format: `- [TAG] [DOMAIN] <body>`');
116	      return;
117	    }
118	
119	    console.log(`\n## RUNTIME_ASSERTIONS (${p0.length} P0 learned rules loaded, BLOCKING at /stage0 decision points)`);
120	    console.log('');
121	    for (const r of p0) {
122	      console.log(`- **[${r.tag}]** ${r.body}`);
123	    }
124	    console.log('');
125	    console.log('**Enforcement targets (wired in /stage0 Step 0.5):**');
126	    console.log('- `[POWER-LAW-MEDIAN-WARNING]` → every revenue claim MUST output P10/P50/P90 (calc-dispatcher power-law-sizer). Median alone = BLOCKING');
127	    console.log('- `[FORUM-LAYER-PRIORITY]` → VN/CN/MMO topics fire forum preflight BEFORE Wave 1 (Phase 2)');
128	    console.log('- `[CONFABULATION-BAN]` → every numeric claim MUST have named+dated+URL-linked source or `[?]` tag');
129	    console.log('- `[FAILURE-ARCHAEOLOGY-MANDATORY]` → failure search required BEFORE supporting evidence');
130	    console.log('- `[TOOL-EXHAUSTION]` → before "not feasible" verdict, exhaust ≥4 distinct tool paths');
131	    console.log('- `[GMV-INCOME-DIVISION]` → creator economy analyses MUST divide GMV × commission ÷ active count');
132	    console.log('- `[FOUNDER-REALITY-GATE]` → audit founder constraints (audience/language/capital/location) before recommending doors');
133	    console.log('');
134	    console.log(`Assertions file: ${filePath || '(write failed — degraded mode)'}`);
135	    console.log('Plan: plans/260413-1002-stage0-bias-fix/phase-01-foundation-learned-rules-and-classifier.md');
136	    console.log('');
137	  }
138	
139	  // Load learned-rules-priority.json (from rule-fire-tracker.py) and re-rank p0 by fire_count.
140	  // If file missing, returns p0 unchanged (graceful degradation).
141	  function rankByFireCount(p0, cwd) {
142	    try {
143	      const priorityPath = path.join(cwd, 'data', 'calibration', 'learned-rules-priority.json');
144	      if (!fs.existsSync(priorityPath)) return p0;
145	      const priority = JSON.parse(fs.readFileSync(priorityPath, 'utf8'));
146	      const rules = priority.rules || [];
147	      if (!rules.length) return p0;
148	
149	      // Build fire_count map: rule_tag -> count
150	      const fireMap = {};
151	      for (const r of rules) {
152	        if (r.rule_tag) fireMap[r.rule_tag] = r.fire_count || 0;
153	      }
154	
155	      // Sort p0 by fire_count desc, preserve order for unranked rules
156	      const ranked = [...p0].sort((a, b) => {
157	        const ca = fireMap[a.tag] || 0;
158	        const cb = fireMap[b.tag] || 0;
159	        return cb - ca;
160	      });
161	
162	      return ranked;
163	    } catch (_) {
164	      return p0; // fail-open
165	    }
166	  }
167	
168	  function main() {
169	    if (!isEnabled()) {
170	      process.exit(0);
171	    }
172	
173	    // Read SessionStart event payload from stdin (Claude Code contract)
174	    const stdin = fs.readFileSync(0, 'utf-8').trim();
175	    const data = stdin ? JSON.parse(stdin) : {};
176	    const sessionId = data.session_id || `anon-${Date.now()}`;
177	
178	    const cwd = process.cwd();
179	    const rulesPath = path.join(cwd, '.claude', 'rules', 'learned-rules.md');
180	    const parsed = parseRules(rulesPath);
181	
182	    if (parsed.error === 'file_not_found') {
183	      console.log(`[stage0-learned-rules-injector] learned-rules.md not found at ${rulesPath} — runtime assertions unavailable`);
184	      process.exit(0);
185	    }
186	
187	    // Phase 8: re-rank p0 rules by fire_count from rule-fire-tracker output (top-5 injected first)
188	    const TOP_N = 5;
189	    const rankedP0 = rankByFireCount(parsed.p0, cwd);
190	    const p0ToInject = rankedP0.slice(0, Math.max(TOP_N, rankedP0.length));
191	
192	    const filePath = writeAssertionsFile(sessionId, p0ToInject, parsed.p1, rulesPath);
193	    emitContextBlock(p0ToInject, filePath);
194	
195	    process.exit(0);
196	  }
197	
198	  main();
199	} catch (e) {
200	  // Minimal crash logging — fail-open, never block session start
201	  try {
202	    const fs = require('fs');
203	    const p = require('path');
204	    const logDir = p.join(__dirname, '.logs');
205	    if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
206	    fs.appendFileSync(
207	      p.join(logDir, 'hook-log.jsonl'),
208	      JSON.stringify({
209	        ts: new Date().toISOString(),
210	        hook: 'stage0-learned-rules-injector',
211	        status: 'crash',
212	        error: e.message,
213	      }) + '\n'
214	    );
215	  } catch {}
216	  process.exit(0);
217	}
